using System; using Inu.Kernel.Storage; namespace Inu.Samples.Filesystem; public static unsafe class Sample { public static Boolean Register(){var cb=new KernelFileSystemCallbacks(&Probe,&Mount,&Unmount,&Open,&Read,null,&Flush,&Close);return KernelVfs.RegisterFileSystem(KernelFileSystemType.Custom,cb);} private static Boolean Probe(KernelStorageVolumeHandle v)=>v.Value!=0U; private static Boolean Mount(KernelStorageVolumeHandle v,UInt64* c){if(c==null)return false;*c=v.Value;return true;} private static Boolean Unmount(UInt64 c)=>c!=0; private static Boolean Open(UInt64 c,String p,UInt32 n,KernelFileAccess a,UInt64* f,KernelFileType* t,UInt64* l){if(c==0||f==null||t==null||l==null)return false;*f=1;*t=KernelFileType.File;*l=0;return true;} private static Boolean Read(UInt64 f,UInt64 o,Byte* b,UInt32 n,UInt32* r){if(r==null)return false;*r=0;return f!=0;} private static Boolean Flush(UInt64 f)=>f!=0; private static Boolean Close(UInt64 f)=>f!=0; }
